functions.body:
block([m,n,L,r,p,st,pv,a,prev],
 m:length(M), n:length(M[1]), L:makelist(makelist(M[i,j],j,1,n),i,1,m), r:1, st:[], pv:[], prev:L,
 for j:1 thru n do if r<=m then (
  p:0,
  for i:r thru m do if L[i][j]#0 then (if p=0 then p:i else if abs(L[i][j])<abs(L[p][j]) then p:i),
  if p>0 then (
   if p#r then L:makelist(if i=p then L[r] elseif i=r then L[p] else L[i],i,1,m),
   L:makelist(if i=r then rowNorm(L[r]) else L[i],i,1,m), a:L[r][j],
   L:makelist(if i=r or L[i][j]=0 then L[i] else rowNorm(a*L[i]-L[i][j]*L[r]),i,1,m),
   pv:endcons(j,pv), r:r+1,
   if L#prev then st:endcons(apply(matrix,L),st), prev:L)),
 L:makelist(if lead(L[i])=0 then L[i] else L[i]/lead(L[i]),i,1,m),
 if L#prev then st:endcons(apply(matrix,L),st),
 [st,pv])

prts.feedbackvariables:
validInput: rowlistp(ans1);
ansAsCols: if validInput then map(transpose, ans1) else []; /*avoid errors due to invalid input*/
subspace: inSpan(map(transpose,rowify(mat)),ansAsCols);
independent: not dependentvects(ansAsCols);
spanning: is(subspace and rank(matrify(ansAsCols))=rankA);

validInput: collistp(ans2);
ans: if validInput then ans2 else []; /*avoid errors due to invalid input*/
subspace: inSpan(cols,ans);
independent: not dependentvects(ans);
spanning: is(subspace and rank(matrify(ans))=rankA);

validInput: collistp(ans3);
ans: if validInput then ans3 else []; /*avoid errors due to invalid input*/
subspace: alltrue(inKer,ans);
independent: not dependentvects(ans);
spanning: is(subspace and rank(matrify(ans))=n-rankA);
